begin;
select no_plan();
do $$ declare s uuid; owner_id uuid:=gen_random_uuid(); clerk_id uuid:=gen_random_uuid(); begin
 insert into auth.users(id) values(owner_id),(clerk_id);
 insert into public.stores default values returning id into s;
 insert into public.staff(user_id,store_id,display_name,role) values(owner_id,s,'Owner','owner'),(clerk_id,s,'Clerk','staff');
 perform public.seed_store_settings(s,'DNS test');
 insert into public.sku_ledger(sku,store_id,issued_at) select x,s,now() from unnest(array['96001','96002','96003','96004','96005','96006']) x;
 insert into public.units(sku,store_id,title,brand,model,state,qty_on_hand,ask_cents,shippable,received_at,updated_at)
 select x,s,case x when '96001' then 'LG refrigerator' when '96002' then 'Refrigerator water filter' else 'Acme toaster' end,'Acme','Toaster','available',case when x='96001' then 3 else 1 end,2500,true,now(),now()
 from unnest(array['96001','96002','96003','96004','96005','96006']) x;
 insert into public.unit_channel_selections(store_id,sku,channel,selected,source) values(s,'96003','ebay',true,'backfill');
 insert into public.listing_queue(store_id,sku,channel,action) values(s,'96003','ebay','list');
 insert into public.listings(store_id,sku,channel,status,listing_id) values(s,'96004','ebay','listed','test-live'),(s,'96004','depop','listed','test-depop');
 perform set_config('dns.owner',owner_id::text,true); perform set_config('dns.clerk',clerk_id::text,true); perform set_config('dns.store',s::text,true);
end $$;
select set_config('request.jwt.claim.sub',current_setting('dns.clerk'),true);
select set_config('request.jwt.claim.role','authenticated',true);
select is(public.portal_unit_dns('96001')->>'dns','true','oversized types automatically DNS');
select is((select shippable from public.units where sku='96001'),false,'DNS cannot ship');
select is((select fulfillment_override from public.units where sku='96001'),'pickup','DNS fulfillment is pickup');
select is(public.portal_unit_dns('96002')->>'dns','false','refrigerator accessories are not automatically DNS');
select lives_ok($$select public.portal_set_unit_dns('96003',true)$$,'clerk can set DNS during receiving');
select is((select selected from public.unit_channel_selections where sku='96003'),false,'DNS clears existing channel selection');
select is((select status from public.listing_queue where sku='96003' and action='list'),'cancelled','DNS cancels pending publishing');
select throws_ok($$select public.portal_set_unit_dns('96001',false)$$,'P0001','DNS is required for this oversized item type','oversized types stay protected');
select is((public.inventory_totals()->>'dns')::int,4,'DNS counts physical quantity');
select is((public.inventory_totals()->>'total')::int,8,'total physical inventory retained');
select is((public.inventory_totals()->>'listed')::int,1,'existing eBay item still counted once');
select is((public.inventory_totals()->>'not_ready')::int,3,'DNS excluded from incomplete shipping stock');
select is((public.staff_inventory_list('','dns',false,'sku',0,24)->'totals'->>'unit_count')::int,2,'clerk has separate DNS tab');
select ok(not exists(select 1 from jsonb_array_elements(public.staff_inventory_list('','dns',false,'sku',0,24)->'items') i where i->>'acquisition_cost_cents' is not null or i->>'sold_price_cents' is not null),'DNS clerk view reveals no cost or sold prices');
select is((select count(*)::int from jsonb_array_elements(public.staff_inventory_list('','in_stock',false,'sku',0,24)->'items') i where i->>'sku' in ('96001','96003')),0,'DNS excluded from clerk sellable stock');
select set_config('request.jwt.claim.sub',current_setting('dns.owner'),true);
select is((select count(*)::int from jsonb_array_elements(public.portal_inventory_list('','dns',false,'sku',0,24)->'items')),2,'admin DNS tab');
select is((select count(*)::int from jsonb_array_elements(public.portal_inventory_list_with_locations('','dns',false,'sku',0,24,'all')->'items')),2,'location-filtered DNS tab');
select is((select count(*)::int from jsonb_array_elements(public.portal_inventory_list('','in_stock',false,'sku',0,24)->'items') i where i->>'sku' in ('96001','96003')),0,'DNS excluded from admin sellable stock');
select is((select count(*)::int from jsonb_array_elements(public.portal_inventory_list('','all',true,'sku',0,24)->'items') i where i->>'sku' in ('96001','96003')),0,'DNS excluded from Unfinished');
select is((select public.unit_listing_gaps(u) from public.units u where sku='96001'),'{}'::text[],'shipping gaps do not put DNS in Unfinished');
select throws_ok($$select public.portal_set_unit_channel_selection('96003','ebay',true)$$,'22023','channel_never_list: DNS - Do not ship','DNS selection blocked even in a new store');
select throws_ok(format('select public.assert_channel_eligible(%L,''96003'',''ebay'')',current_setting('dns.store')),'P0001','DNS: Do not ship - never list on eBay, Amazon, TikTok Shop or Depop','eBay publishing blocked');
select throws_ok(format('select public.floor_category_pre_push(%L,''96003'',''amazon'')',current_setting('dns.store')),'P0001','DNS: Do not ship - never list on eBay, Amazon, TikTok Shop or Depop','Amazon pre-push blocked');
select throws_ok(format('select public.floor_category_pre_push(%L,''96003'',''tiktok'')',current_setting('dns.store')),'P0001','DNS: Do not ship - never list on eBay, Amazon, TikTok Shop or Depop','TikTok pre-push blocked');
select throws_ok(format('select public.floor_bundle_push_gate(%L,''96003'',''depop'')',current_setting('dns.store')),'P0001','DNS: Do not ship - never list on eBay, Amazon, TikTok Shop or Depop','Depop publishing blocked');
select lives_ok($$select public.portal_set_unit_dns('96004',true)$$,'DNS handles an already-live item');
select is((select count(*)::int from public.listing_queue where sku='96004' and channel='ebay' and action='end' and status='queued'),1,'existing live eBay listing queued to end');
select is((select count(*)::int from public.delist_tasks where sku='96004' and channel='depop' and completed_at is null),1,'manual Depop delisting task created');
insert into public.floor_bundles(store_id,sku,main_sku) values(current_setting('dns.store')::uuid,'96006','96005');
insert into public.floor_bundle_components(store_id,bundle_sku,component_sku,quantity,prior_show_on_website) values(current_setting('dns.store')::uuid,'96006','96003',1,false);
select throws_ok(format('select public.floor_bundle_push_gate(%L,''96006'',''ebay'')',current_setting('dns.store')),'P0001','DNS: Do not ship - never list on eBay, Amazon, TikTok Shop or Depop','bundle cannot bypass component DNS');
select lives_ok($$select public.portal_set_unit_dns('96003',false)$$,'manual DNS can be cleared for ordinary item');
select is((select selected from public.unit_channel_selections where sku='96003'),false,'clearing DNS never auto relists');
select is((select sum(ask_cents)::int from public.units),15000,'prices unchanged');
select is((select sum(qty_on_hand)::int from public.units),8,'quantity unchanged');
select is((select count(*)::int from public.sales),0,'no sales created or modified');
select is((select count(*)::int from public.events where field='DNS'),4,'DNS changes audited');
select is(public.unit_dns_type(jsonb_populate_record(null::public.units,jsonb_build_object('title',title))),expected,'classification: '||title)
from (values ('French door fridge',true),('Chest freezer',true),('Deep fryer',true),('Dishwasher',true),('Queen mattress',true),('Metal bed frame',true),('Sectional sofa',true),('Electric scooter',true),('Air fryer',false),('Mattress protector',false),('Mattress pad',false),('Mattress topper',false),('Dishwasher hose',false)) t(title,expected);
select * from finish();
rollback;
